?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Queries | kgnst.com</title><link rel="stylesheet" href="assets/style.css"></head><body class="admin-page"><header class="admin-header"><div><span class="eyebrow">KGNST.COM ADMIN</span><h1>Student queries</h1></div><div><span>Signed in as <?=esc($_SESSION['admin_name'])?></span><a class="button small" href="admin.php">Student records</a><a class="button small" href="logout.php">Log out</a></div></header><main class="records"><div class="record-summary"><strong><?=count($queries)?></strong><span>Total queries</span></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Contact</th><th>Course</th><th>Query</th><th>Received</th></tr></thead><tbody><?php if (!$queries): ?><tr><td colspan="5" class="empty">No queries received yet.</td></tr><?php else: foreach ($queries as $query): ?><tr><td><b><?=esc($query['full_name'])?></b></td><td><?=esc($query['phone'])?><br><small><?=esc($query['email'])?></small></td><td><?=esc($query['course'] ?: '—')?></td><td><?=nl2br(esc($query['message']))?></td><td><?=esc(date('d M Y, h:i A', strtotime($query['created_at'])))?></td></tr><?php endforeach; endif; ?></tbody></table></div></main></body></html>
